 for(let i=0;i<6;i++){const a=i*Math.PI/3,[x,z]=polar(a,7.5);pumpkin(festive,x,z,.35);const bench=new T.Group();bench.position.set(...[...polar(a+.25,7.8).slice(0,1),0,polar(a+.25,7.8)[1]]);bench.rotation.y=a;world.add(bench);furniture('GF-194',bench,1.8,[0,0,0]);const p=polar(a,9.3),q=polar(a+Math.PI/3,9.3);for(const [xx,zz]of[p,q])part(festive,'cylinder','#78665b',[.06,3.8,.06],[xx,1.9,zz]);bunting(festive,[p[0],3.8,p[1]],[q[0],3.8,q[1]]);}
 furniture('BA-0012',world,2.2,[0,0,0]);for(const [x,z]of[[-1.2,.8],[1.3,.5],[0,-1.5]])pumpkin(festive,x,z,.42);furniture('GF-025',world,.55,[1.4,0,-.8]);
