function whole(){selected=null;camera.position.set(39,47,57);controls.target.set(0,0,0);controls.update();}
function cutaway(){for(const b of buildingMeshes){b.roof.visible=!$('cutaway').checked;b.lintel.visible=!$('cutaway').checked;for(const pane of b.windows)pane.visible=!$('cutaway').checked;for(const m of b.walls){m.scale.y=$('cutaway').checked?.65:2.6;m.position.y=$('cutaway').checked?.325:1.3;}}}
