$('generate').onclick=rebuild;$('pause').textContent=paused?'Resume':'Pause';$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause';};$('whole').onclick=whole;$('door').onclick=()=>{selected=null;const h=town.houses[0],p=housePoint(h,13.5);camera.position.set(p[0]+5,5.5,p[1]-6);controls.target.set(p[0],1,p[1]+1.5);controls.update();};$('cutaway').onchange=cutaway;$('night').onchange=lighting;$('decor').onchange=()=>decorations.forEach(g=>g.visible=$('decor').checked);
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,pack:'halloween-v1',...town},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`lantern-lane-${town.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
