new ResizeObserver(()=>{const r=$('viewport').getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe($('viewport'));
function frame(now){const realDt=Math.min(.05,(now-last)/1000||0);last=now;if(town&&!document.hidden){const dt=paused?0:realDt*Number($('speed').value);advanceTown(town,dt);for(const p of town.people){const m=visitors[p.id],moving=['walk','approach','depart','leave'].includes(p.state);animateCreature(m,dt,p.state==='greet'||p.state==='gift'?'greet':moving?'walk':'idle',paused);m.position.x=p.position[0];m.position.z=p.position[1];m.rotation.y=p.heading;const gift=giftMeshes[p.id];gift.visible=p.state==='gift';if(gift.visible){const start=housePoint(town.houses[p.target],15.45),t=Math.min(1,p.timer/1.2);gift.position.set(start[0]+(p.position[0]-start[0])*t,1.1+Math.sin(t*Math.PI)*.25,start[1]+(p.position[1]-start[1])*t);}}
 for(let i=0;i<hosts.length;i++)animatePerson(hosts[i],{phase:town.houses[i].active!==null?'work':'home'},0,dt,paused);for(const g of decorations)for(const child of g.children)if(child.userData.festival)animateCreature(child,dt,'idle',paused);
 if(selected!==null){const p=town.people[selected],target=new T.Vector3(p.position[0],1,p.position[1]),shift=target.sub(controls.target).multiplyScalar(1-Math.exp(-realDt*5));controls.target.add(shift);camera.position.add(shift);}uiClock+=realDt;if(uiClock>.2){ui();uiClock=0;}controls.update();renderer.render(scene,camera);renderer.domElement.dataset.paused=String(paused);}requestAnimationFrame(frame);}
async function init(){rebuild();requestAnimationFrame(frame);const loader=new GLTFLoader();const results=await Promise.allSettled(['GF-194','BA-0012','GF-025'].map(async id=>templates.set(id,(await loader.loadAsync(`/domestic-assets/${id}.glb`)).scene)));if(results.every(r=>r.status==='fulfilled')){$('assets').textContent='Reused: town character rig, shared hex building kit, GF-194 benches, BA-0012 market table, GF-025 supply crate, and the Halloween creature pack.';rebuild();}else $('assets').textContent='Some furniture assets could not load. The town and trick-or-treat loop remain available.';}init().catch(e=>{$('status').textContent='The town could not load. Please reload.';console.error(e);});
